output_text:
[
  {
    "id": "return_cart_to_top_left_bay",
    "text": "Anyone who takes a cart is obliged to return it to the designated cart-return bay at the top-left before the trip ends.",
    "abstraction": {
      "state_properties": {
        "at_return_bay": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "at_return_bay",
              "hasCart"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "cart_drop_only_at_return_bay",
    "text": "It is forbidden to leave a cart anywhere except the designated return bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "at_return_bay": "at(0,1)"
      },
      "events": {
        "cart_drop": {
          "pre": "LEAVE_CART",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_drop",
          {
            "not": "at_return_bay"
          }
        ]
      }
    }
  },
  {
    "id": "exit_only_after_cart_returned",
    "text": "It is forbidden to exit the supermarket unless the shopping cart has already been parked in the return bay.",
    "abstraction": {
      "state_properties": {
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "cart_parked_in_return_bay"
          }
        ]
      }
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "It is forbidden to leave the store while still holding or pushing a shopping cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          "pushing_cart"
        ]
      }
    }
  },
  {
    "id": "must_take_cart_before_shopping",
    "text": "At the start of a shopping trip, the shopper is obliged to take the available cart before completing the trip.",
    "abstraction": {
      "state_properties": {
        "at_start_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "take_start_cart": {
          "pre": {
            "and": [
              "PICKUP_CART",
              "at_start_cart_station"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_start_cart"
    }
  },
  {
    "id": "no_hand_carrying_items",
    "text": "It is forbidden to carry grocery items by hand rather than placing them in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "pickup_items_only_with_cart",
    "text": "It is forbidden to pick up an item unless the shopper currently has the cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart"
      },
      "events": {
        "item_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "item_pickup",
          {
            "not": "pushing_cart"
          }
        ]
      }
    }
  },
  {
    "id": "no_interactions_after_cart_return",
    "text": "After the cart has been returned to the bay, it is forbidden to perform any further interaction before exiting.",
    "abstraction": {
      "state_properties": {
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "cart_parked_in_return_bay",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  }
]
